1937	  const finalizarPicking = async () => {
1938	    if (finalizando) return; // Guard local contra duplo-clique
1939	    if (!requisicaoId) return;
1940	
1941	    const itensNaoColetados = itens.filter(
1942	      (item) => !(String(item.quantidade_enviada || '').trim() !== ''),
1943	    );
1944	    if (itensNaoColetados.length > 0) {
1945	      toast({
1946	        title: 'Atenção',
1947	        description: `Ainda há ${itensNaoColetados.length} itens não coletados.`,
1948	        variant: 'destructive',
1949	      });
1950	      return;
1951	    }
1952	
1953	    let statusReserved = false;
1954	    try {
1955	      setFinalizando(true);
1956	
1957	      // === GUARD DE RACE CONDITION ===
1958	      // Estratégia: fazer o UPDATE atômico em_progresso -> finalizada ANTES de deduzir estoque.
1959	      // O PostgreSQL serializa UPDATEs concorrentes na mesma linha, então apenas uma sessão
1960	      // conseguirá afetar a linha; as demais receberão 0 rows e abortarão.
1961	      // Se a dedução posterior falhar, revertemos o status no bloco catch.
1962	      const { data: reserveData, error: reserveError } = await supabase
1963	        .from('requisicoes' as any)
1964	        .update({ status: 'finalizada' })
1965	        .eq('id', requisicaoId)
1966	        .eq('status', 'em_progresso')
1967	        .select('id');
1968	
1969	      if (reserveError) throw reserveError;
1970	
1971	      const affected =
1972	        reserveData && Array.isArray(reserveData) ? reserveData.length : 0;
1973	
1974	      if (affected === 0) {
1975	        // Outra sessão já finalizou, ou o status não era 'em_progresso'.
1976	        // Verifica o status atual para dar feedback preciso.
1977	        const { data: currentReq } = await supabase
1978	          .from('requisicoes' as any)
1979	          .select('status')
1980	          .eq('id', requisicaoId)
1981	          .single();
1982	
1983	        const currentStatus = (currentReq as { status?: string } | null)?.status;
1984	        const normalizedCurrent = normalizeRequisicaoStatus(currentStatus);
1985	
1986	        if (normalizedCurrent === 'finalizada') {
1987	          toast({
1988	            title: 'Já finalizada',
1989	            description: 'Esta requisição já foi finalizada por outra sessão.',
