const finalizarPicking = async () => {
  if (finalizando) return; // Guard local contra duplo-clique
  if (!requisicaoId) return;

  const itensNaoColetados = itens.filter(
    (item) => !(String(item.quantidade_enviada || '').trim() !== ''),
  );
  if (itensNaoColetados.length > 0) {
    toast({
      title: 'Atenção',
      description: `Ainda há ${itensNaoColetados.length} itens não coletados.`,
      variant: 'destructive',
    });
    return;
  }

  let statusReserved = false;
  try {
    setFinalizando(true);

    // === GUARD DE RACE CONDITION ===
    // Estratégia: fazer o UPDATE atômico em_progresso -> finalizada ANTES de deduzir estoque.
    // O PostgreSQL serializa UPDATEs concorrentes na mesma linha, então apenas uma sessão
    // conseguirá afetar a linha; as demais receberão 0 rows e abortarão.
    // Se a dedução posterior falhar, revertemos o status no bloco catch.
    const { data: reserveData, error: reserveError } = await supabase
      .from('requisicoes' as any)
      .update({ status: 'finalizada' })
      .eq('id', requisicaoId)
      .eq('status', 'em_progresso')
      .select('id');

    if (reserveError) throw reserveError;

    const affected =
      reserveData && Array.isArray(reserveData) ? reserveData.length : 0;

    if (affected === 0) {
      // Outra sessão já finalizou, ou o status não era 'em_progresso'.
      // Verifica o status atual para dar feedback preciso.
      const { data: currentReq } = await supabase
        .from('requisicoes' as any)
        .select('status')
        .eq('id', requisicaoId)
        .single();

      const currentStatus = (currentReq as { status?: string } | null)?.status;
      const normalizedCurrent = normalizeRequisicaoStatus(currentStatus);

      if (normalizedCurrent === 'finalizada') {
        toast({
          title: 'Já finalizada',
          description: 'Esta requisição já foi finalizada por outra sessão.',
          variant: 'destructive',
        });
        navigate('/logistica');
      } else {
        toast({
          title: 'Não foi possível finalizar',
          description: `Status inesperado: ${currentStatus || 'desconhecido'}. Recarregue a página.`,
          variant: 'destructive',
        });
      }
      return;
    }

    statusReserved = true;

    // 2. Gerar saídas de estoque para todas as etiquetas QR bipadas nesta requisição.
    //    A RPC é idempotente: re-executar não duplica saídas.
    //    Tipos ainda não regenerados (migration pendente de apply) — usar cast as any
    //    igual ao padrão já consagrado em bipar_etiqueta.
    const { data: saidaRes, error: saidaErr } = await (supabase.rpc as any)(
      'dar_saida_requisicao',
      { p_requisicao_id: Number(requisicaoId) },
    );

    if (saidaErr || saidaRes?.ok === false) {
      const errMsg = saidaErr?.message || saidaRes?.error || 'erro desconhecido';
      wideError('picking.dar_saida_requisicao_erro', errMsg, {
        domain: 'requisicoes',
        attributes: { requisicaoId },
      });
      // Falha pós-reserva: reverter status para em_progresso para permitir retry.
      throw new Error(
        `Requisição não finalizada: falha ao dar baixa no estoque — ${errMsg}. Tente novamente.`,
      );
    }

    // 3. Registrar conclusão no Control Tower.
    await logSeparationCompleted(
      Number(requisicaoId),
      myProfileName,
      reqInfo?.loja_solicitante || 'Loja',
      itens.length,
    );

    // 4. Log user event (broadcast to other users in real-time)
    if (user) {
      const nomeUser = myProfileName;
      channelRef.current?.send({
        type: 'broadcast',
        event: 'user_event',
        payload: { text: `${nomeUser} finalizou a separação` },
      });
    }

    // 5. Toast de sucesso resumindo as saídas geradas.
    const etiquetasProcessadas = (saidaRes?.etiquetas_processadas as number) ?? 0;
    const jaProcessadas = (saidaRes?.ja_processadas as number) ?? 0;
    const jaProcessadasSufixo =
      jaProcessadas > 0 ? ` (${jaProcessadas} já processadas)` : '';
    toast({
      title: 'Requisição finalizada',
      description: `${etiquetasProcessadas} saída(s) de estoque registrada(s)${jaProcessadasSufixo}.`,
    });

    // 6. Toast de alerta para itens com saldo insuficiente (zerados na saída).
    const alertas = saidaRes?.alertas;
    if (Array.isArray(alertas) && alertas.length > 0) {
      toast({
        title: 'Atenção: saldo insuficiente',
        description: `${alertas.length} item(ns) com saldo insuficiente — saldo zerado.`,
        variant: 'destructive',
      });
    }

    // 7. Exibir dialog de resumo das saídas geradas.
    //    A navegação para /logistica acontece quando o usuário fecha o dialog.
    setShowResumoSaida(true);
  } catch (error) {
    handleError(error, { domain: 'requisicoes', operation: 'finalizarSeparacao', showToast: false });

    // Se o status foi reservado (foi para 'finalizada') mas a operação posterior falhou,
    // tenta reverter para 'em_progresso' para que a separação possa ser retomada.
    if (statusReserved) {
      const errorMessage =
        error instanceof Error ? error.message : 'Erro ao processar finalização. Tente novamente.';
      try {
        await supabase
          .from('requisicoes' as any)
          .update({ status: 'em_progresso' })
          .eq('id', requisicaoId)
          .eq('status', 'finalizada');
        toast({
          title: 'Erro ao finalizar',
          description: errorMessage,
          variant: 'destructive',
        });
      } catch (revertErr) {
        handleError(revertErr, { domain: 'requisicoes', operation: 'finalizarSeparacaoRevert', showToast: false });
        toast({
          title: 'Erro grave',
          description:
            'A finalização falhou e a reversão do status também. Contate o suporte imediatamente.',
          variant: 'destructive',
        });
      }
    } else {
      toast({

