  // Progresso ponderado pela quantidade solicitada de cada item.
  // Itens com quantidade 0 (ou inválida) contam como binário (coletado / não coletado)
  // para não distorcer o cálculo.
  let totalPeso = 0;
  let totalEnviadoPeso = 0;

  for (const item of itens) {
    const solicitada = Number(item.quantidade) || 0;
    const enviada = parseFloat(item.quantidade_enviada || '0');
    const enviadaValida = Number.isFinite(enviada) && enviada > 0 ? enviada : 0;

    if (solicitada > 0) {
      totalPeso += solicitada;
      // Clampa entre 0 e solicitada para não passar de 100% por item
      totalEnviadoPeso += Math.min(enviadaValida, solicitada);
    } else {
      // Fallback binário: 1 ponto por item, 1 se marcado
      totalPeso += 1;
      if (String(item.quantidade_enviada || '').trim() !== '') {
        totalEnviadoPeso += 1;
      }
    }
  }

  if (totalPeso === 0) return 0;
  return Math.round((totalEnviadoPeso / totalPeso) * 100);
};

